--------------------------------------------------------------------------------
--- 独立符卡名横幅（从 boss.sc_name 抽出，去掉 boss 依赖与历史记录）
--- 坐标系：世界坐标（与 boss.sc_name 一致，不调 SetViewMode）
---   → 作为普通 object 在 ObjRender 阶段渲染，用的就是 world 视图
---   → self.x/self.y 与 player.x/player.y 同一坐标系，可直接比较
--- 位置参考 boss 符卡名（终点 x=192、从右侧 +200 滑入），最终 y 默认更低
--- 保留原版“自机靠近淡出、离开恢复”机制
---
--- 用法：
---   Include('THlib/player/hifuu/merry/spellcard_name_banner.lua')
---   New(aya_sp_name_banner, "神奈川冲浪里")            -- 全默认，位置比 boss 符卡名低
---   New(aya_sp_name_banner, "神奈川冲浪里", 192, 150)  -- 指定终点 (192,150)
---
--- 复用的全局资源（THlib 已加载）：
---   贴图 boss_spell_name_bg（右对齐锚点 256×36）、TTF 字体 sc_name
--------------------------------------------------------------------------------

-- boss 符卡名横幅的基准（世界坐标，见 boss_ui.lua 的 sc_name）
local BOSS_SC_X       = 192  -- boss 符卡名终点 x（世界坐标，右边缘）
local BOSS_SC_Y       = 236  -- boss 符卡名终点 y
local BOSS_SC_XOFFSET = 200  -- 从右侧滑入的初始横向偏移
-- 本横幅最终 y 比 boss 符卡名低的量（世界坐标 y 向上，正数=更靠下）
local LOWER_BY        = 45

---@class aya_sp_name_banner
aya_sp_name_banner = Class(object)

--- 初始化（不传的参数一律回退到 boss 符卡名基准，最终 y 自动放低）
---@param text string       显示文本
---@param x1 number|nil      最终 x（默认 192，同 boss 符卡名）
---@param y1 number|nil      最终 y（默认 boss 符卡名 y - LOWER_BY）
---@param x0 number|nil      起始 x（默认 = 最终 x + 200，同 boss 从右滑入）
---@param y0 number|nil      起始 y（默认 = 最终 y）
---@param move_time number|nil  滑入用时（帧），默认 30
---@param hold_time number|nil  停留时长（帧）；nil = 常驻直到手动 Del
function aya_sp_name_banner:init(text, x1, y1, x0, y0, show_time, move_time, hold_time)
    self.layer = LAYER_TOP + 1
    self.group = GROUP_GHOST
    self.bound = false

    self.text = text or ""
    -- 最终位置：参考 boss 符卡名，y 默认放低
    self.x1 = x1 or BOSS_SC_X
    self.y1 = y1 or (BOSS_SC_Y - LOWER_BY)
    -- 起始位置：默认与 boss 一样从右侧滑入（终点 + 横向偏移），y 与终点同高
    self.x0 = x0 or (self.x1 + BOSS_SC_XOFFSET)
    self.y0 = y0 or self.y1
    self.show_time = show_time or 30
    self.move_time = move_time or 30
    self.hold_time = hold_time -- nil 则常驻

    self.x = self.x0
    self.y = self.y0
    self._alpha  = 0   -- 整体透明度 0-1
    self._scale  = 5   -- 文字初始放大（回弹到 1，制造“啪”地弹出感）
    self._scale2 = 1   -- 背景条附加缩放系数（1→0）
    self.flag    = 0   -- 自机靠近计数（0~18），越大越淡
end

function aya_sp_name_banner:frame()
	local st = self.show_time
    local mt = self.move_time
    local t  = self.timer

    if t <= st then
        -- 滑入 + 缩放回弹（sin 为角度制，sin(90*p) 实现缓出）
        local p = t / (st)
        local e = sin(90 * p)
        self._alpha  = p
        self._scale  = 1 + 4 * (1 - e) -- 5 → 1
        self._scale2 = 1 - e           -- 1 → 0
    elseif t <= mt + st then
    	local p = (t - st) / (mt)
        local e = sin(90 * p)
    	self.x = self.x0 + (self.x1 - self.x0) * e
        self.y = self.y0 + (self.y1 - self.y0) * e
    else
        self.x = self.x1
        self.y = self.y1
        self._alpha  = 1
        self._scale  = 1
        self._scale2 = 0
    end

    -- 自机靠近淡出、离开恢复（照抄 boss.sc_name 逻辑，世界坐标直接比较）
    -- flag 每帧 ±1，夹在 0~18；render 时 alpha 乘 (1 - flag/30)，最低约 0.4
    local near = false
    if t > mt and IsValid(player)
            and abs(player.x - self.x) <= 180
            and abs(player.y - self.y) <= 60 then
        near = true
    end
    if near then
        self.flag = self.flag + 1
    else
        self.flag = self.flag - 1
    end
    self.flag = min(max(0, self.flag), 18)

    -- 有停留时长则到点淡出并自删；否则常驻，需外部 Del
    if self.hold_time and t > mt + self.hold_time then
        self._alpha = self._alpha - 1 / 20
        if self._alpha <= 0 then
            Del(self)
        end
    end
end

function aya_sp_name_banner:render()
    -- 不调 SetViewMode：与 boss.sc_name 一致，用 ObjRender 阶段的世界视图

    -- 靠近淡出系数（1 = 正常，最低约 0.4）
    local near_fade = 1 - self.flag / 30
    local a = self._alpha * near_fade * 255

    -- 背景条（锚点右对齐 256 宽，故向 self.x 左侧延伸）
    SetImageState("boss_spell_name_bg", "", Color(a, 255, 255, 255))
    Render("boss_spell_name_bg", self.x, self.y, 0, 1 + 0.5 * self._scale2)

    -- 文字：先画 8 方向黑描边，再画白字（与原版一致）
    local ty = self.y - 10
    local s = GetImageScale()
    SetImageScale(s * self._scale)
    local d = sqrt(2)
    for i = 0, 8 do
        local _x = self.x + d * cos(i * 45)
        local _y = ty + d * sin(i * 45)
        RenderTTF("main_font_zh_cn", self.text,
                _x, _x, _y - 2, _y - 2,
                Color(a, 0, 0, 0),
                "right", "noclip")
    end
    RenderTTF("main_font_zh_cn", self.text,
            self.x, self.x, ty - 2, ty - 2,
            Color(a, 255, 255, 255),
            "right", "noclip")
    SetImageScale(s)
end

_editor_class["sc_1_p1_bu1"]=Class(bullet)
_editor_class["sc_1_p1_bu1"].init=function(self,_x,_y,angle,v)
bullet.init(self,water_drop_dark,COLOR_DEEP_BLUE,true,true)
self.x,self.y=_x,_y
    _object.set_color(self,"mul+add",255,30,52,183)
    self.bound = false
    lasttask=task.New(self,function()
        do local a,_d_a=(angle),(0.6) for _=1,60 do
            SetV2(self,v,a,true,false)
            task._Wait(1)
        a=a+_d_a end end
        do local a,_d_a=(self._angle),(ran:Float(-0.8,-1.0)) for _=1,ran:Int(150, 180) do
            SetV2(self,v,a,true,false)
            task._Wait(1)
        a=a+_d_a end end
        self.bound = true
        local p = ran:Int(0,10)
        if p >=0 and p <= 1 then
            PlaySound("don00",0.1,self.x/256,false)
            last=New(_straight,ball_small,COLOR_GRAY,self.x,self.y,2,self._angle,false,0,false,true,0,false,0,0,0,false)
            _set_g(last,0.05)
            _forbid_v(last,'original','original',2)
            last.timer=11
            _del(self,true)
        elseif p <= 9 then
            _del(self,true)
        end
        _set_g(self,0.05)
        _forbid_v(self,'original','original',2)
        for _=1,_infinite do
            self.navi = true
            task._Wait(1)
        end
    end)
end
