                            task._Wait(10)
                        end
                    end
                end
            a=a+_d_a t=t+_d_t end end
        end)
        lasttask=task.New(self,function()
            task._Wait(60)
            task.MoveTo(-170, 224,180,MOVE_ACC_DEC)
