_editor_class["sc_2_crow"].init=function(self,_x,_y,angle, d, rot, type)
    self.x,self.y=_x,_y
    self.img="ani:crow"
    self.layer=LAYER_ENEMY
    self.group=GROUP_ENEMY
    self.hide=false
    self.bound=true
    self.navi=false
    self.hp=200
    self.maxhp=200
    self.colli=true
    self._servants={}
    self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    self.type = type
    self.bound = false
    self.hit = false
    lasttask=task.New(self,function()
        do local i,_d_i=(0),(255/50) for _=1,50 do
            _object.set_color(self,"mul+alpha",i,255,255,255)
            task._Wait(1)
        i=i+_d_i end end
    end)
    lasttask=task.New(self,function()
        do local r,_d_r,d1,_d_d1=(angle),(rot),(0),(d / 50) for _=1,_infinite do
            _set_rel_pos(self,min(d, d1) * cos(r), min(d, d1) * sin(r),self.rot,false)
            if self.hit then
                if IsValid(_boss) then
                _boss.crow_drank = self
                end
                PlaySound("ice",1.0,self.x/256,true)
                do break end
            else
            end
            task._Wait(1)
        r=r+_d_r d1=d1+_d_d1 end end
        _object.set_color(self,"mul+alpha",255,239,46,46)
        self.group = GROUP_INDES
        New(boss_cast_ef,self.x,self.y)
        task._Wait(60)
        PlaySound("old_power0",1.0,self.x/256,true)
        do
            task.MoveTo(-220,0,60,MOVE_ACCEL)
            task.MoveTo(220,ran:Float(100,140),60,MOVE_NORMAL)
            task.MoveTo(-220,ran:Float(100,140),30,MOVE_NORMAL)
            task.MoveTo(220,ran:Float(100,140),15,MOVE_NORMAL)
            task.MoveTo(-220,ran:Float(100,140),15,MOVE_NORMAL)
            self.colli = false
            for _=1,15 do
                last=New(_editor_class["sc_2_la"],-400, ran:Float(140, 100),30, ran:Float(-20, 20))
                task._Wait(10)
                last=New(_editor_class["sc_2_la"],400, ran:Float(140, 100),30, ran:Float(160, 200))
                task._Wait(10)
            end
            task._Wait(120)
            _del(self,true)
        end
