_tmp_sc=boss.card.New("伊奘诺「神秘的具象」",50,50,50,1800,{0,0,0},false)
function _tmp_sc:before()
    last=New(_editor_class["NB_Portrait_AI"],0,0,_)
    self.spellname=aic.ui.NewSpellname(self, '伊奘诺「神秘的具象」')
end
function _tmp_sc:init()
    lasttask=task.New(self,function()
        --[[ 这个弹设是两三年前的，所以写得非常烂，但莫名奇妙地产生了一种周期性变化，所以就不过多改动了
        ]]
        task.MoveTo(0,0,60,MOVE_ACC_DEC)
        local N=(10)
        local list=({})
        for i=1,N do
            list[i]=0
        end
        do local sign,_d_sign=(1),(1) for _=1,12 do
            do local n,_d_n=(1),(1) for _=1,N do
                last=New(_editor_class["sc5_slave"],self.x,self.y,n,sign%2,N,list)
            n=n+_d_n end end
            for _,unit in ObjList(GROUP_ENEMY) do
                lasttask=task.New(unit,function()
                    local self=task.GetSelf()
                    do
                        local _beg_r=20 local r=_beg_r local _end_r=120 local _d_r=(_end_r-_beg_r)/(120-1)
                        for _=1,120 do
                            self.r=r
                            task._Wait(1)
                            r=r+_d_r
                        end
                    end
                end)
            end
            task._Wait(120)
            for _,unit in ObjList(GROUP_ENEMY) do
                lasttask=task.New(unit,function()
                    local self=task.GetSelf()
                    do
                        local _beg_r=120 local r=_beg_r local _end_r=20 local _d_r=(_end_r-_beg_r)/(120-1)
                        for _=1,120 do
                            self.r=r
                            task._Wait(1)
                            r=r+_d_r
                        end
                    end
                end)
            end
            task._Wait(120)
            self.group=GROUP_GHOST
            for _,unit in ObjList(GROUP_ENEMY) do
                _kill(unit,true)
            end
            self.group=GROUP_ENEMY
        sign=sign+_d_sign end end
    end)
end
function _tmp_sc:beforedel()
end
function _tmp_sc:del()
    if IsValid(self.spellname) then
        _del(self.spellname,true)
    else
    end
end
function _tmp_sc:after()
end
